{
  "status": "ready",
  "questions": [],
  "model": {
    "name": "产品A和B的整数产量优化",
    "assumptions": [
      "产品A和产品B的产量按整件计，取非负整数。",
      "工时和原料消耗与产量成正比。",
      "本期可用工时上限为100小时，原料上限为80千克。",
      "无其他限制。"
    ],
    "variables": [
      {
        "name": "x_A",
        "description": "产品A的产量",
        "unit": "件",
        "kind": "integer",
        "lower": 0,
        "upper": null
      },
      {
        "name": "x_B",
        "description": "产品B的产量",
        "unit": "件",
        "kind": "integer",
        "lower": 0,
        "upper": null
      }
    ],
    "objective": {
      "sense": "max",
      "terms": [
        {
          "variable": "x_A",
          "coefficient": 40
        },
        {
          "variable": "x_B",
          "coefficient": 30
        }
      ],
      "unit": "元"
    },
    "constraints": [
      {
        "name": "工时限制",
        "terms": [
          {
            "variable": "x_A",
            "coefficient": 2
          },
          {
            "variable": "x_B",
            "coefficient": 1
          }
        ],
        "sense": "<=",
        "rhs": 100,
        "unit": "小时"
      },
      {
        "name": "原料限制",
        "terms": [
          {
            "variable": "x_A",
            "coefficient": 1
          },
          {
            "variable": "x_B",
            "coefficient": 2
          }
        ],
        "sense": "<=",
        "rhs": 80,
        "unit": "千克"
      }
    ]
  }
}
